('original:economics--supply-and-demand:economics--supply-and-demand--18',1,'{"question":"A drought reduces the apple harvest. Which change best represents this?","choices":["A rightward shift of apple demand caused directly by drought","Movement along unchanged supply caused only by a lower price","A leftward shift of apple supply","An increase in the number of apple sellers"],"answer":2,"explanation":""}'::jsonb,'2e4ae6ed6bc4ba61284d73751ee606b8','official',NULL,NULL,'Supply and Demand'),
('original:economics--supply-and-demand:economics--supply-and-demand--19',1,'{"question":"A product''s price falls and buyers purchase more, with other factors unchanged. What occurred?","choices":["An increase in demand shifting the curve","An increase in quantity demanded along the curve","A decrease in supply shifting the curve","A decrease in quantity demanded along the curve"],"answer":1,"explanation":""}'::jsonb,'829af5481a07f751e46da3b3c05c9e37','official',NULL,NULL,'Supply and Demand'),
('original:economics--supply-and-demand:economics--supply-and-demand--20',1,'{"question":"Both demand and supply increase. What can be concluded without knowing their relative sizes?","choices":["Equilibrium price necessarily rises","Equilibrium quantity necessarily falls","Equilibrium price necessarily falls","Equilibrium quantity rises, but the price change is uncertain"],"answer":3,"explanation":""}'::jsonb,'c90eb412d5a895dbc602139ca0527a86','official',NULL,NULL,'Supply and Demand'),
('original:economics--gdp:economics--gdp--1',1,'{"question":"What does gross domestic product measure?","choices":["The value of all financial assets owned by citizens","The market value of final goods and services produced within a country during a period","Only wages earned by government employees","Only goods exported to other countries"],"answer":1,"explanation":""}'::jsonb,'788ebd0d33f7e4217414557b0f976bf9','official',NULL,NULL,'GDP'),
