('original:economics--gdp:economics--gdp--12',1,'{"question":"Why is real GDP more useful for comparing output over time?","choices":["It includes every unpaid household activity","It measures income distribution exactly","It separates output changes from price changes","It eliminates all data estimation"],"answer":2,"explanation":""}'::jsonb,'8e6d0cca1691f4693294b3bf40b4f728','official',NULL,NULL,'GDP'),
