('original:economics--comparative-advantage:economics--comparative-advantage--1',1,'{"question":"What determines comparative advantage?","choices":["Lower opportunity cost of producing a good","Lower total population","A larger national land area","A stronger currency by itself"],"answer":0,"explanation":""}'::jsonb,'5ebdb6aae204e91e46a74574b9d044d7','official',NULL,NULL,'Comparative Advantage'),
('original:economics--comparative-advantage:economics--comparative-advantage--2',1,'{"question":"What determines absolute advantage?","choices":["Producing a good with a lower opportunity cost","Trading a good at a lower exchange rate","Producing a good with fewer inputs per unit","Exporting a good in a larger total quantity"],"answer":2,"explanation":""}'::jsonb,'43228d65b0f3857dddac2e96ea754b9b','official',NULL,NULL,'Comparative Advantage'),
