('original:economics--comparative-advantage:economics--comparative-advantage--8',1,'{"question":"Why can a producer with absolute advantage in both goods still benefit from trade?","choices":["Absolute advantage eliminates every trade-off","Trade requires both producers to have identical productivity","A more productive producer cannot import goods","Relative opportunity costs may differ between producers"],"answer":3,"explanation":""}'::jsonb,'cecfaaacb61f20adc0506dc0ececa505','official',NULL,NULL,'Comparative Advantage'),
