('original:economics--budgeting:economics--budgeting--8',1,'{"question":"Why should a budget usually be based on take-home pay?","choices":["Gross pay always equals available cash","Deductions are paid back automatically each month","Taxes affect only businesses","That is the income available after payroll deductions"],"answer":3,"explanation":""}'::jsonb,'253bef964a8d61c5b6b9a2469c390324','official',NULL,NULL,'Budgeting'),
('original:economics--budgeting:economics--budgeting--9',1,'{"question":"Why should irregular expenses be included in planning?","choices":["Costs may be due later even without a payment this month","Annual bills should count only if they occur every month","Only fixed monthly expenses affect the household''s available income","Future expenses can be ignored until the exact due date"],"answer":0,"explanation":""}'::jsonb,'06382b07de8ffdc28b4d4ea23b08f2c4','official',NULL,NULL,'Budgeting'),
