('original:economics--budgeting:economics--budgeting--12',1,'{"question":"How does cash-flow timing differ from a monthly total?","choices":["Timing measures only a household''s total net worth","A positive monthly total guarantees enough cash every day","Timing is unrelated to pay dates","Timing concerns when money arrives and bills must be paid"],"answer":3,"explanation":""}'::jsonb,'6d86e6b322e92918df93efcb78305339','official',NULL,NULL,'Budgeting'),
('original:economics--budgeting:economics--budgeting--13',1,'{"question":"Why can a realistic budget change over time?","choices":["Income, prices, obligations, and goals may change","Every budget must remain unchanged permanently","Only people with no income can revise budgets","Past spending determines all future expenses exactly"],"answer":0,"explanation":""}'::jsonb,'20ce7ef634959dbde269b90de8b1b31e','official',NULL,NULL,'Budgeting'),
