('original:geography--five-themes-of-geography:geography--five-themes-of-geography--3',1,'{"question":"Which theme examines how people adapt to and change their surroundings?","choices":["Absolute location","Human-environment interaction","Region alone","Relative location"],"answer":1,"explanation":""}'::jsonb,'e52a4447e12b59f3aad602d10ac5c23a','official',NULL,NULL,'Five Themes of Geography'),
('original:geography--five-themes-of-geography:geography--five-themes-of-geography--4',1,'{"question":"Which theme examines flows of people, goods, and ideas?","choices":["Place","Location","Region","Movement"],"answer":3,"explanation":""}'::jsonb,'d68054490816552fdcff0d56649a8483','official',NULL,NULL,'Five Themes of Geography'),
('original:geography--five-themes-of-geography:geography--five-themes-of-geography--5',1,'{"question":"Which theme groups places by shared characteristics?","choices":["Region","Movement","Absolute location","Human-environment interaction"],"answer":0,"explanation":""}'::jsonb,'b32bc2eb3555600a8f8d5844a7eb75d7','official',NULL,NULL,'Five Themes of Geography'),
