('original:geography--physical-geography:geography--physical-geography--1',1,'{"question":"What does physical geography study?","choices":["Only election districts","Only language distribution","Natural features and processes of Earth","Only international trade prices"],"answer":2,"explanation":""}'::jsonb,'2c8c6c922152c09d09515ad5bd4311ce','official',NULL,NULL,'Physical Geography'),
