('original:geography--physical-geography:geography--physical-geography--6',1,'{"question":"What is a delta?","choices":["A steep cliff formed only by earthquakes","A mountain peak shaped only by wind","A sediment-built landform near a river''s mouth","A dry basin with no river connection"],"answer":2,"explanation":""}'::jsonb,'7a9cee6633fa6a226aa3fc7322697e0d','official',NULL,NULL,'Physical Geography'),
