('original:geography--physical-geography:geography--physical-geography--8',1,'{"question":"How can moving tectonic plates shape landscapes?","choices":["They change only the amount of rainfall","They determine every cultural boundary","They prevent earthquakes from occurring","They can build mountains, produce faults, and generate volcanic activity"],"answer":3,"explanation":""}'::jsonb,'31625078e47bd4dc6f437dafb868d3f2','official',NULL,NULL,'Physical Geography'),
('original:geography--physical-geography:geography--physical-geography--9',1,'{"question":"What happens at a convergent plate boundary?","choices":["Plates move toward one another","Plates move apart","Plates slide past one another only","No relative movement occurs"],"answer":0,"explanation":""}'::jsonb,'02731d2283ebd3b7c740d2f24da55898','official',NULL,NULL,'Physical Geography'),
('original:geography--physical-geography:geography--physical-geography--10',1,'{"question":"How can glaciers reshape land?","choices":["Ice has no effect on rock beneath it","Glaciers operate only in tropical lowlands","Moving ice erodes rock and transports sediment","Glaciers form all rivers through volcanic activity"],"answer":2,"explanation":""}'::jsonb,'43d144781302587c0541051036e1f8a1','official',NULL,NULL,'Physical Geography'),
('original:geography--physical-geography:geography--physical-geography--11',1,'{"question":"Why do rivers often deposit sediment when flow slows?","choices":["Slower water always carries larger particles than fast water","Slower water has less ability to carry some sediment","Sediment can settle only on mountain summits","Rivers transport only dissolved gases"],"answer":1,"explanation":""}'::jsonb,'62b478734cab5ca49e5fd80b96106f6a','official',NULL,NULL,'Physical Geography'),
('original:geography--physical-geography:geography--physical-geography--12',1,'{"question":"How does groundwater relate to surface water?","choices":["The two systems are always completely disconnected","Groundwater exists only beneath oceans","All groundwater remains permanently frozen","Water can move between underground storage and streams or springs"],"answer":3,"explanation":""}'::jsonb,'5d12dedbe42da4c3638ff6847e8acedd','official',NULL,NULL,'Physical Geography'),
('original:geography--physical-geography:geography--physical-geography--13',1,'{"question":"What processes connect stages of the water cycle?","choices":["Evaporation, condensation, precipitation, and movement through land and water","Only volcanic eruptions and earthquakes","Only political changes and urban migration","Only tides and changes in currency values"],"answer":0,"explanation":""}'::jsonb,'373d308abe5dde2ee901767adf0bf07f','official',NULL,NULL,'Physical Geography'),
('original:geography--physical-geography:geography--physical-geography--14',1,'{"question":"Why do floodplains often have fertile soils?","choices":["Floodplains never receive sediment","Every floodplain consists only of bare rock","Flooding can deposit nutrient-bearing sediment","Flooding permanently prevents plant growth"],"answer":2,"explanation":""}'::jsonb,'4f5112b11363782dcb86eec63a73b92b','official',NULL,NULL,'Physical Geography'),
('original:geography--physical-geography:geography--physical-geography--15',1,'{"question":"Why can landforms change at different rates?","choices":["All landforms change at exactly the same speed","Slow processes and sudden events can both reshape terrain","Only human construction changes landscapes","Every mountain forms in a single storm"],"answer":1,"explanation":""}'::jsonb,'e16cad20677b75382f930b2ae25a9ea1','official',NULL,NULL,'Physical Geography'),
