('original:geography--population:geography--population--14',1,'{"question":"Why can rapid city growth pressure infrastructure?","choices":["Cities have unlimited water supplies by definition","Population growth removes the need for schools","Housing, transport, and services may not expand as quickly as population","Infrastructure adjusts instantly without investment"],"answer":2,"explanation":""}'::jsonb,'2b4fbe6a7c3930874057d564b6c392f3','official',NULL,NULL,'Population'),
('original:geography--population:geography--population--15',1,'{"question":"Why should demographic models be applied cautiously?","choices":["Models make observation unnecessary","Countries'' histories and conditions do not follow one identical path","Every country''s population changes at the same rate","Migration has no effect on demographic patterns"],"answer":1,"explanation":""}'::jsonb,'f04b201efb618f5eb0cbae27b8e583df','official',NULL,NULL,'Population'),
