('original:geography--population:geography--population--20',1,'{"question":"A large young generation enters childbearing ages even as fertility declines. What process can sustain growth?","choices":["Complete demographic decline","Negative net migration alone","A decrease in the number of potential parents","Population momentum"],"answer":3,"explanation":""}'::jsonb,'e860b9381a60cc271c5dfb30de2ec1cc','official',NULL,NULL,'Population'),
('original:geography--migration:geography--migration--1',1,'{"question":"What is migration in human geography?","choices":["Movement of people involving a change in usual residence","Any shipment of goods between ports","Only travel for a one-day holiday","Only changes in a city''s street names"],"answer":0,"explanation":""}'::jsonb,'86df0b8b9ccc4e601697913444dde2d4','official',NULL,NULL,'Migration'),
('original:geography--migration:geography--migration--2',1,'{"question":"What is immigration?","choices":["Movement out of a country to live elsewhere","Movement of goods across a border","Movement into a country to live there","Movement between rooms in one home"],"answer":2,"explanation":""}'::jsonb,'eaa44bb192cd438e2717cd839cfeb0c3','official',NULL,NULL,'Migration'),
