('original:geography--migration:geography--migration--4',1,'{"question":"What is internal migration?","choices":["A move between two sovereign countries","A daily trip to work without changing residence","A shipment of products between factories","A residential move within the same country"],"answer":3,"explanation":""}'::jsonb,'06515b19ae9596560d95ad508b2e2d59','official',NULL,NULL,'Migration'),
('original:geography--migration:geography--migration--5',1,'{"question":"What is a push factor?","choices":["A condition encouraging people to leave a place","A condition attracting people to a destination","A map''s measure of elevation","An official count of imports"],"answer":0,"explanation":""}'::jsonb,'1fe01819274973ff4095448a5203bc4b','official',NULL,NULL,'Migration'),
