('original:geography--migration:geography--migration--7',1,'{"question":"What are remittances?","choices":["Taxes paid only on imported vehicles","Money migrants send to people in their place of origin","Payments governments make to foreign armies","The total cost of building a highway"],"answer":1,"explanation":""}'::jsonb,'33479b081213b0b43b2bba5c2660835d','official',NULL,NULL,'Migration'),
('original:geography--migration:geography--migration--8',1,'{"question":"Why can jobs influence migration?","choices":["Employment has no relationship to residential decisions","Only retired people can migrate for economic reasons","Every migrant is guaranteed work on arrival","People may move toward employment or away from limited opportunities"],"answer":3,"explanation":""}'::jsonb,'1fe04e802b7eabf035bcdf80bac348bc','official',NULL,NULL,'Migration'),
('original:geography--migration:geography--migration--9',1,'{"question":"How can family networks affect migration?","choices":["They may provide information, housing, and support for newcomers","They eliminate every legal and financial barrier","They require every family member to move at once","They prevent migrants from maintaining ties across borders"],"answer":0,"explanation":""}'::jsonb,'b27fc645b44720ce129084e19a35a138','official',NULL,NULL,'Migration'),
