('original:social-studies--economics--entrepreneurship-and-small-business:social-studies--economics--entrepreneurship-and-small-business--4',1,'{"question":"What does break-even mean for a business?","choices":["Total revenue equals total costs","Sales are greater than every possible cost","The business has no customers","The business has repaid all future expenses"],"answer":0,"explanation":""}'::jsonb,'f7c195ba1144670625064483632f0b9f','official',NULL,NULL,'Entrepreneurship and Small Business'),
('original:social-studies--economics--entrepreneurship-and-small-business:social-studies--economics--entrepreneurship-and-small-business--5',1,'{"question":"Why should an entrepreneur research potential customers before launching a product?","choices":["Research guarantees the venture will succeed","Research can test whether a real need and market exist","Research removes all startup costs","Research determines the final profit with certainty"],"answer":1,"explanation":""}'::jsonb,'70c700ed176fbf7b65ffd730928471fc','official',NULL,NULL,'Entrepreneurship and Small Business'),
('original:social-studies--economics--entrepreneurship-and-small-business:social-studies--economics--entrepreneurship-and-small-business--6',1,'{"question":"A business has high fixed costs but low variable cost per item. Which statement about those costs is accurate?","choices":["Variable costs remain constant at every output level","Fixed costs are paid only when the business earns a profit","Fixed costs do not change directly with the number of units produced in the short run","Variable costs cannot include materials"],"answer":2,"explanation":""}'::jsonb,'fb4bdf0e7d0f068800e8e4fdad60659a','official',NULL,NULL,'Entrepreneurship and Small Business'),
('original:social-studies--economics--entrepreneurship-and-small-business:social-studies--economics--entrepreneurship-and-small-business--7',1,'{"question":"A bakery sells each box for $12. Its ingredients and packaging cost $5 per box, and monthly fixed costs are $700. What does the $7 difference represent?","choices":["The bakery''s total monthly revenue","A fixed cost per box regardless of sales","The owner''s net income after taxes","Contribution toward fixed costs and then profit"],"answer":3,"explanation":""}'::jsonb,'9922fe18df24be7a69bc9780bafed273','official',NULL,NULL,'Entrepreneurship and Small Business'),
('original:social-studies--economics--entrepreneurship-and-small-business:social-studies--economics--entrepreneurship-and-small-business--8',1,'{"question":"A business plan is most useful when it","choices":["clarifies the product, customers, operations, funding, and assumptions","guarantees a bank loan","replaces market research and testing","predicts exact profits for every future year"],"answer":0,"explanation":""}'::jsonb,'7f5c75c877d115ccfc03921e0c50bafd','official',NULL,NULL,'Entrepreneurship and Small Business'),
('original:social-studies--economics--entrepreneurship-and-small-business:social-studies--economics--entrepreneurship-and-small-business--9',1,'{"question":"A startup has strong sales but often cannot pay bills when due. Which issue is most likely?","choices":["A lack of customer interest by definition","A cash-flow timing problem","A surplus of long-term profit","A change in its legal business name"],"answer":1,"explanation":""}'::jsonb,'4705c3f0d53a706376d8e64aa590a367','official',NULL,NULL,'Entrepreneurship and Small Business'),
('original:social-studies--economics--entrepreneurship-and-small-business:social-studies--economics--entrepreneurship-and-small-business--10',1,'{"question":"Why might an entrepreneur test a small prototype or pilot before a full launch?","choices":["To avoid hearing from customers","To guarantee that no competitor will enter","To gather evidence about usability, costs, and customer response","To set prices without considering expenses"],"answer":2,"explanation":""}'::jsonb,'b2161027133c27b780f85b21e3982ce1','official',NULL,NULL,'Entrepreneurship and Small Business'),
('original:social-studies--economics--entrepreneurship-and-small-business:social-studies--economics--entrepreneurship-and-small-business--11',1,'{"question":"A business''s total costs are $2,400 per month. It earns $8 for each item sold and has no other revenue. How many items must it sell to break even?","choices":["192","30","2,408","300"],"answer":3,"explanation":""}'::jsonb,'c8692f4b3d1ae18ea5ef6b6e145de05c','official',NULL,NULL,'Entrepreneurship and Small Business'),
('original:social-studies--economics--entrepreneurship-and-small-business:social-studies--economics--entrepreneurship-and-small-business--12',1,'{"question":"Which action best protects a business''s cash flow during a slow sales period?","choices":["Forecast receipts and expenses and maintain a suitable cash reserve","Spend all available cash before invoices arrive","Record expenses only at the end of the year","Assume profit and cash balance are always identical"],"answer":0,"explanation":""}'::jsonb,'4789b34fede18f2f7231fcd69dc7cee3','official',NULL,NULL,'Entrepreneurship and Small Business'),
('original:social-studies--economics--entrepreneurship-and-small-business:social-studies--economics--entrepreneurship-and-small-business--13',1,'{"question":"What is a target market?","choices":["The list of all suppliers in an economy","The group of customers a business aims to serve","The total cost of equipment","The government''s annual tax revenue"],"answer":1,"explanation":""}'::jsonb,'c85bf61478b160c024059902915ea338','official',NULL,NULL,'Entrepreneurship and Small Business'),
('original:social-studies--economics--entrepreneurship-and-small-business:social-studies--economics--entrepreneurship-and-small-business--14',1,'{"question":"A small business finds that customers value convenient pickup more than decorative packaging. What is a useful response?","choices":["Ignore customer feedback because the first plan cannot change","Increase packaging costs automatically","Adjust the offer based on customer evidence and evaluate the result","Stop measuring customer preferences"],"answer":2,"explanation":""}'::jsonb,'97796213f244a473bec5eb595b05dca0','official',NULL,NULL,'Entrepreneurship and Small Business'),
('original:social-studies--economics--entrepreneurship-and-small-business:social-studies--economics--entrepreneurship-and-small-business--15',1,'{"question":"Which ownership structure generally separates a corporation''s legal identity from its owners?","choices":["Sole proprietorship","Informal partnership with no registration","Independent contractor agreement","Corporation"],"answer":3,"explanation":""}'::jsonb,'3c2398646815f258649ecae241084dbd','official',NULL,NULL,'Entrepreneurship and Small Business'),
('original:social-studies--economics--entrepreneurship-and-small-business:social-studies--economics--entrepreneurship-and-small-business--16',1,'{"question":"A sole proprietor and a partner want to share ownership and decision-making. Which issue should they address early?","choices":["How responsibilities, contributions, profits, and disputes will be handled","How to avoid keeping any financial records","How to guarantee that demand never changes","How to eliminate every business risk"],"answer":0,"explanation":""}'::jsonb,'e4184d26d2d793826abc58a3374a5287','official',NULL,NULL,'Entrepreneurship and Small Business'),
('original:social-studies--economics--entrepreneurship-and-small-business:social-studies--economics--entrepreneurship-and-small-business--17',1,'{"question":"What is a variable cost for a candle-making business?","choices":["Monthly rent for the workshop","Wax used to make each candle","An annual business license fee","A fixed insurance premium"],"answer":1,"explanation":""}'::jsonb,'719a0ac2ef5c5b6a0a5a54808113895e','official',NULL,NULL,'Entrepreneurship and Small Business'),
('original:social-studies--economics--entrepreneurship-and-small-business:social-studies--economics--entrepreneurship-and-small-business--18',1,'{"question":"A business sells a new product at a price below its cost for each unit. What must it consider to remain sustainable?","choices":["Whether it can ignore unit costs forever","Whether lower prices guarantee profit","Whether other revenue or a deliberate short-term strategy can cover the loss","Whether customers will pay the business''s fixed costs automatically"],"answer":2,"explanation":""}'::jsonb,'e9436172d13d7d048d859f2c2ae62bd3','official',NULL,NULL,'Entrepreneurship and Small Business'),
('original:social-studies--economics--entrepreneurship-and-small-business:social-studies--economics--entrepreneurship-and-small-business--19',1,'{"question":"Why should a small business keep accurate financial records?","choices":["Records ensure that expenses never occur","Records make customer research unnecessary","Records replace the need to track revenue","Records support cash planning, tax reporting, and informed decisions"],"answer":3,"explanation":""}'::jsonb,'11c80345c98bd289f2353e42cb391ee7','official',NULL,NULL,'Entrepreneurship and Small Business'),
('original:social-studies--economics--entrepreneurship-and-small-business:social-studies--economics--entrepreneurship-and-small-business--20',1,'{"question":"A company wants to use a competitor''s logo because customers recognize it. What is the best next step?","choices":["Develop its own brand identity and respect trademark rights","Copy the logo but change one letter","Use the logo only in paid advertisements","Assume brand ownership ends when a business is small"],"answer":0,"explanation":""}'::jsonb,'1fa13ec296f49af71d88903dee1c7be6','official',NULL,NULL,'Entrepreneurship and Small Business'),
('original:social-studies--geography--urban-geography-and-development:social-studies--geography--urban-geography-and-development--1',1,'{"question":"Urbanization is the process by which","choices":["cities lose all connections to rural regions","a growing share of a population lives in urban areas","farms replace transportation networks","a country''s population becomes evenly distributed"],"answer":1,"explanation":""}'::jsonb,'e6ffd204139aaa527010728acce89a4e','official',NULL,NULL,'Urban Geography and Development'),
('original:social-studies--geography--urban-geography-and-development:social-studies--geography--urban-geography-and-development--2',1,'{"question":"What is a central business district (CBD)?","choices":["A rural area with few services","A boundary used only for national elections","A city''s major concentration of commercial and office activity","A zone reserved for agriculture"],"answer":2,"explanation":""}'::jsonb,'39b10173b0a746830f8d9c3f9a2298f5','official',NULL,NULL,'Urban Geography and Development'),
('original:social-studies--geography--urban-geography-and-development:social-studies--geography--urban-geography-and-development--3',1,'{"question":"A city expands outward as residents move to homes farther from the center. This pattern is often called","choices":["counterurbanization","urban renewal","industrialization","suburbanization"],"answer":3,"explanation":""}'::jsonb,'6daca1f5f13c1755791a0e9c17d7e284','official',NULL,NULL,'Urban Geography and Development'),
('original:social-studies--geography--urban-geography-and-development:social-studies--geography--urban-geography-and-development--4',1,'{"question":"Why can access to public transit influence where people live and work?","choices":["Transit changes travel time and the set of places people can reach","Transit determines a city''s climate","Transit removes the need for land-use planning","Transit makes all neighborhoods identical"],"answer":0,"explanation":""}'::jsonb,'f2dccde916925bef5b08fd6b3ff17f97','official',NULL,NULL,'Urban Geography and Development'),
('original:social-studies--geography--urban-geography-and-development:social-studies--geography--urban-geography-and-development--5',1,'{"question":"A neighborhood gains new investment and housing costs rise, pushing some long-time residents to move. This process may be described as","choices":["rural depopulation","gentrification","desertification","deindustrialization"],"answer":1,"explanation":""}'::jsonb,'7503854c9581769bf2e4708809e077bd','official',NULL,NULL,'Urban Geography and Development'),
('original:social-studies--geography--urban-geography-and-development:social-studies--geography--urban-geography-and-development--6',1,'{"question":"Which condition most directly contributes to an urban heat island?","choices":["A city''s elevation always increases its temperature","Urban areas receive no rainfall","Buildings and paved surfaces absorb and retain more heat than nearby vegetated areas","Trees release heat into every street"],"answer":2,"explanation":""}'::jsonb,'3825c80682081eeea22b6cd1bbdea157','official',NULL,NULL,'Urban Geography and Development'),
('original:social-studies--geography--urban-geography-and-development:social-studies--geography--urban-geography-and-development--7',1,'{"question":"A planner wants to reduce flood risk in a rapidly growing city. Which measure is most likely to help?","choices":["Cover open land with more pavement","Build homes only in low-lying flood zones","Remove drainage channels without alternatives","Protect wetlands and use permeable surfaces to absorb stormwater"],"answer":3,"explanation":""}'::jsonb,'87dd991540de66a8a58d925032055090','official',NULL,NULL,'Urban Geography and Development'),
('original:social-studies--geography--urban-geography-and-development:social-studies--geography--urban-geography-and-development--8',1,'{"question":"Why might informal settlements develop at the edges of a fast-growing city?","choices":["Housing and infrastructure may not expand as quickly or affordably as the population","Residents prefer to live without access to services","Cities have no land-use decisions","Urban migration always results from one cause"],"answer":0,"explanation":""}'::jsonb,'6d0473eafbf564f4e3a69dda0e03e333','official',NULL,NULL,'Urban Geography and Development'),
('original:social-studies--geography--urban-geography-and-development:social-studies--geography--urban-geography-and-development--9',1,'{"question":"Which data would best help compare access to parks across neighborhoods?","choices":["The number of city council meetings held each year","The distance or travel time from residents'' homes to public green space","The height of the tallest downtown building","The city''s average annual rainfall alone"],"answer":1,"explanation":""}'::jsonb,'1f7166a5dc8bb8b30fdc3e9a7e9925b3','official',NULL,NULL,'Urban Geography and Development'),
('original:social-studies--geography--urban-geography-and-development:social-studies--geography--urban-geography-and-development--10',1,'{"question":"A city places homes, shops, and services near a train station. What goal does this pattern often support?","choices":["Greater dependence on long car trips","Lower access to public transportation","More compact, transit-oriented development","Separation of all daily activities"],"answer":2,"explanation":""}'::jsonb,'ca8959e0c693edb2fad0fb4b6758d29d','official',NULL,NULL,'Urban Geography and Development'),
('original:social-studies--geography--urban-geography-and-development:social-studies--geography--urban-geography-and-development--11',1,'{"question":"Why can zoning decisions affect social and economic patterns within a city?","choices":["They determine the national currency","They make land values unrelated to location","They eliminate the need for transportation","They shape which activities and buildings are allowed in different areas"],"answer":3,"explanation":""}'::jsonb,'27c03b49f7c1d5eee9228a0313b17add','official',NULL,NULL,'Urban Geography and Development'),
('original:social-studies--geography--urban-geography-and-development:social-studies--geography--urban-geography-and-development--12',1,'{"question":"A new highway shortens commute times for one suburb but divides a nearby neighborhood. What should a planning review include?","choices":["Both transportation benefits and the distribution of social and environmental costs","Only the projected vehicle speed","Only the highway''s construction materials","A decision to exclude affected residents from the analysis"],"answer":0,"explanation":""}'::jsonb,'6eda2e04d6e0304f72f1dba8487087fa','official',NULL,NULL,'Urban Geography and Development'),
('original:social-studies--geography--urban-geography-and-development:social-studies--geography--urban-geography-and-development--13',1,'{"question":"Which factor is most likely to attract businesses to a particular urban location?","choices":["Distance from every worker and customer","Access to customers, workers, transportation, and supporting services","Lack of reliable utilities","A location with no connection to suppliers"],"answer":1,"explanation":""}'::jsonb,'ce148a6f751a22776b4a936515f4e32e','official',NULL,NULL,'Urban Geography and Development'),
('original:social-studies--geography--urban-geography-and-development:social-studies--geography--urban-geography-and-development--14',1,'{"question":"An urban population grows quickly, but the number of schools and water connections stays the same. What challenge may result?","choices":["Population density automatically declines","The city''s tax base must disappear","Public services may not meet residents'' needs","The region becomes rural"],"answer":2,"explanation":""}'::jsonb,'d47f6e4767e4404b8b262aca634f119b','official',NULL,NULL,'Urban Geography and Development'),
('original:social-studies--geography--urban-geography-and-development:social-studies--geography--urban-geography-and-development--15',1,'{"question":"Which strategy can improve a neighborhood''s walkability?","choices":["Separate homes from all daily services","Remove shade and pedestrian crossings","Require a car for every local trip","Create connected sidewalks, safe crossings, and nearby destinations"],"answer":3,"explanation":""}'::jsonb,'5cc64e6fe5e42c1f9b0fa8377eb5dbad','official',NULL,NULL,'Urban Geography and Development'),
('original:social-studies--geography--urban-geography-and-development:social-studies--geography--urban-geography-and-development--16',1,'{"question":"A city measures the number of residents per square kilometer. What is it measuring?","choices":["Population density","Population growth rate","Natural increase","Net migration"],"answer":0,"explanation":""}'::jsonb,'bc60951593d658d50b661a4e81c5a28a','official',NULL,NULL,'Urban Geography and Development')
insert into public.question_content_versions(source_key,version_number,question,content_hash,source_type,creator_id,source_set_id,source_title) values
('original:social-studies--geography--urban-geography-and-development:social-studies--geography--urban-geography-and-development--17',1,'{"question":"A downtown office district loses employers, while warehouses and service businesses grow in a nearby area. What geographic idea helps explain this shift?","choices":["A permanent uniform pattern of city development","Changes in land use and economic activity over time","A change in latitude","A movement of tectonic plates"],"answer":1,"explanation":""}'::jsonb,'260cc85b1859c8fc3652509a5da738b9','official',NULL,NULL,'Urban Geography and Development'),
('original:social-studies--geography--urban-geography-and-development:social-studies--geography--urban-geography-and-development--18',1,'{"question":"Why should urban development plans consider residents'' access to clean water and sanitation?","choices":["They matter only in rural regions","They are unrelated to city infrastructure","These services affect health, opportunity, and quality of life","They make population data unnecessary"],"answer":2,"explanation":""}'::jsonb,'8f4262217699a15ff96cdf818731bdf2','official',NULL,NULL,'Urban Geography and Development'),
('original:social-studies--geography--urban-geography-and-development:social-studies--geography--urban-geography-and-development--19',1,'{"question":"A city is comparing two housing plans. Plan A adds more units near existing transit; Plan B expands into farmland far from services. Which comparison is most complete?","choices":["Compare only the number of buildings","Assume the larger land area always costs less","Ignore access to jobs and public services","Compare affordability, travel, infrastructure costs, land use, and environmental effects"],"answer":3,"explanation":""}'::jsonb,'4f322a8cf717cae1423a80b22fa415ff','official',NULL,NULL,'Urban Geography and Development'),
('original:social-studies--geography--urban-geography-and-development:social-studies--geography--urban-geography-and-development--20',1,'{"question":"Why do some cities adopt mixed-use zoning?","choices":["It can place housing, shops, and services closer together","It prevents people from walking between destinations","It requires every neighborhood to have the same density","It eliminates the need to manage traffic"],"answer":0,"explanation":""}'::jsonb,'ebd99c9dc07b58d6f833b4d55fc18dac','official',NULL,NULL,'Urban Geography and Development'),
('original:social-studies--geography--economic-geography:social-studies--geography--economic-geography--1',1,'{"question":"Economic geography studies how","choices":["political borders change without regard to people","economic activities are distributed across places and connected to geographic conditions","weather operates without affecting human activity","individual firms set national laws"],"answer":1,"explanation":""}'::jsonb,'454b9d7da97a76d666c1efc38bd74bdd','official',NULL,NULL,'Economic Geography'),
('original:social-studies--geography--economic-geography:social-studies--geography--economic-geography--2',1,'{"question":"A factory locates near a port to reduce shipping time for imported materials. Which location factor is most important?","choices":["Climate classification","Population density alone","Transportation access","National language"],"answer":2,"explanation":""}'::jsonb,'74ef1cffc32210a440cfb0157e1373fe','official',NULL,NULL,'Economic Geography'),
('original:social-studies--geography--economic-geography:social-studies--geography--economic-geography--3',1,'{"question":"Several technology firms locate near one another and share workers and suppliers. This clustering is called","choices":["suburbanization","subsistence farming","cultural diffusion","agglomeration"],"answer":3,"explanation":""}'::jsonb,'d3c9d3e248a5fb03c74e6d4904c00da5','official',NULL,NULL,'Economic Geography'),
('original:social-studies--geography--economic-geography:social-studies--geography--economic-geography--4',1,'{"question":"A region grows wheat efficiently while another produces electronics efficiently. Specialization can support trade because each region may","choices":["focus on activities where it has a comparative advantage","produce every good at the same cost","avoid all transportation costs","become independent of consumers"],"answer":0,"explanation":""}'::jsonb,'709ab5d5f19de91ee7f7e93acb95595f','official',NULL,NULL,'Economic Geography'),
('original:social-studies--geography--economic-geography:social-studies--geography--economic-geography--5',1,'{"question":"Why have many manufacturers located some production near ports or major transport corridors?","choices":["Ports eliminate the need for workers","Those locations can reduce the cost and time of moving inputs and finished products","Transport corridors determine consumer preferences","Manufacturing cannot operate inland"],"answer":1,"explanation":""}'::jsonb,'e7bdda2832a9f6acf8b017b7e31566c9','official',NULL,NULL,'Economic Geography'),
('original:social-studies--geography--economic-geography:social-studies--geography--economic-geography--6',1,'{"question":"A mining region sells raw minerals abroad but imports many finished products. Which economic pattern may this illustrate?","choices":["Complete control of all stages of production","Economic isolation from trade","Unequal positions in a global production chain","A lack of natural resources"],"answer":2,"explanation":""}'::jsonb,'dc9a650ecff013207519b1b33916f251','official',NULL,NULL,'Economic Geography'),
('original:social-studies--geography--economic-geography:social-studies--geography--economic-geography--7',1,'{"question":"Which indicator can help compare the overall economic output produced within a country?","choices":["Population density","Average elevation","Annual hours of daylight","Gross domestic product"],"answer":3,"explanation":""}'::jsonb,'3e3bc33968d55569736babd4a1221179','official',NULL,NULL,'Economic Geography'),
('original:social-studies--geography--economic-geography:social-studies--geography--economic-geography--8',1,'{"question":"Why should GDP per capita be interpreted cautiously as a measure of development?","choices":["It is an average and does not show how income is distributed or every dimension of well-being","It measures only a country''s total land area","It directly counts every person''s wealth","It excludes all economic production"],"answer":0,"explanation":""}'::jsonb,'0176cd3332fdb06253e61ba2bfc992e1','official',NULL,NULL,'Economic Geography'),
('original:social-studies--geography--economic-geography:social-studies--geography--economic-geography--9',1,'{"question":"An agricultural region shifts from small farms to mechanized commercial production. What may happen to employment patterns?","choices":["All residents must become farmers","Fewer workers may be needed per unit of output, while other jobs may grow in processing or services","Production must decline to zero","Transportation becomes unnecessary"],"answer":1,"explanation":""}'::jsonb,'0074a8259a1a2f72213407269ccebb8d','official',NULL,NULL,'Economic Geography'),
('original:social-studies--geography--economic-geography:social-studies--geography--economic-geography--10',1,'{"question":"A company chooses to locate near a university, skilled workers, and research facilities. Which factor is likely influencing its decision?","choices":["Distance from every supplier","A desire to avoid innovation","Access to specialized knowledge and labor","The region''s political map color"],"answer":2,"explanation":""}'::jsonb,'a52b6e1634f8928c52930c7795edcf2d','official',NULL,NULL,'Economic Geography'),
('original:social-studies--geography--economic-geography:social-studies--geography--economic-geography--11',1,'{"question":"Why can a region''s physical geography influence its economic activities?","choices":["Physical geography fully determines every person''s occupation","Geography prevents regions from trading","Resources have no effect on production","Climate, terrain, water, and resources can affect costs and opportunities"],"answer":3,"explanation":""}'::jsonb,'131251c9077507887bacf12501f4ba74','official',NULL,NULL,'Economic Geography'),
('original:social-studies--geography--economic-geography:social-studies--geography--economic-geography--12',1,'{"question":"An exporter can produce a good at lower opportunity cost than its trading partners. This describes","choices":["comparative advantage","a trade deficit","a price ceiling","a labor surplus"],"answer":0,"explanation":""}'::jsonb,'2dc8ccbaa0a8b5634f0754fd625d4550','official',NULL,NULL,'Economic Geography'),
('original:social-studies--geography--economic-geography:social-studies--geography--economic-geography--13',1,'{"question":"A coastal region has growing tourism but also faces seasonal employment and pressure on water resources. What is the best geographic analysis?","choices":["Count visitor arrivals and ignore local effects","Consider economic benefits alongside seasonal labor and environmental limits","Assume tourism has identical impacts in every place","Treat water supply as unrelated to tourism"],"answer":1,"explanation":""}'::jsonb,'6e33c6370f2e0b53db45e3c021ed547b','official',NULL,NULL,'Economic Geography'),
('original:social-studies--geography--economic-geography:social-studies--geography--economic-geography--14',1,'{"question":"What is one potential effect of a new highway linking an inland city to a seaport?","choices":["It guarantees every local firm will expand","It eliminates trade with other regions","It may lower transport costs and change where firms choose to locate","It changes a region''s natural resources"],"answer":2,"explanation":""}'::jsonb,'565867c72dd6202d3edd75ea0ff7c2de','official',NULL,NULL,'Economic Geography'),
('original:social-studies--geography--economic-geography:social-studies--geography--economic-geography--15',1,'{"question":"A region''s economy relies heavily on one crop. Why can this increase economic vulnerability?","choices":["Crop specialization prevents all market changes","One crop guarantees stable household incomes","A single crop removes the need for trade","A disease, price drop, or weather shock can affect many producers at once"],"answer":3,"explanation":""}'::jsonb,'7905f2c7789fefadf8427711a307af54','official',NULL,NULL,'Economic Geography'),
('original:social-studies--geography--economic-geography:social-studies--geography--economic-geography--16',1,'{"question":"Which activity belongs primarily to the tertiary sector?","choices":["Providing medical care","Extracting iron ore","Growing rice","Manufacturing steel"],"answer":0,"explanation":""}'::jsonb,'41f1a8cd15a1454d7e60a27a00de5bbc','official',NULL,NULL,'Economic Geography'),
('original:social-studies--geography--economic-geography:social-studies--geography--economic-geography--17',1,'{"question":"As countries industrialize, employment often shifts from agriculture toward","choices":["subsistence hunting only","manufacturing and services","unpaid household work exclusively","mining in every region"],"answer":1,"explanation":""}'::jsonb,'c4f7d19315d1eb59305886262dee1ec9','official',NULL,NULL,'Economic Geography'),
