('original:social-studies--world-history--early-humans-and-river-valley-civilizations:social-studies--world-history--early-humans-and-river-valley-civilizations--9',1,'{"question":"Which feature is most associated with the Indus Valley cities of Harappa and Mohenjo-daro?","choices":["Stone castles built for medieval knights","Planned streets and drainage systems","Paved Roman aqueducts","A network of Inca roads"],"answer":1,"explanation":""}'::jsonb,'bf4331466a3f67d2f5250bf042eb1aa3','official',NULL,NULL,'Early Humans and River Valley Civilizations'),
('original:social-studies--world-history--early-humans-and-river-valley-civilizations:social-studies--world-history--early-humans-and-river-valley-civilizations--10',1,'{"question":"What is one reason historians study artifacts from early societies?","choices":["Artifacts reveal every individual''s thoughts","Artifacts replace all written evidence","Artifacts provide evidence about technology, trade, and daily life","Artifacts always identify their original owners"],"answer":2,"explanation":""}'::jsonb,'ff0f6c223fae2c94682d7576bee15dcf','official',NULL,NULL,'Early Humans and River Valley Civilizations'),
('original:social-studies--world-history--early-humans-and-river-valley-civilizations:social-studies--world-history--early-humans-and-river-valley-civilizations--11',1,'{"question":"Why did written records matter to some early states?","choices":["They ended the need for communication","They made government unnecessary","They guaranteed that every person could read","They helped record transactions, laws, taxes, or administration"],"answer":3,"explanation":""}'::jsonb,'47e69a597849295ff4bd8ef3455d919e','official',NULL,NULL,'Early Humans and River Valley Civilizations'),
('original:social-studies--world-history--early-humans-and-river-valley-civilizations:social-studies--world-history--early-humans-and-river-valley-civilizations--12',1,'{"question":"A river floods unpredictably, damaging fields. Which response could help a community reduce risk?","choices":["Build and maintain systems for managing water and storing food","Move every settlement into a desert","Stop observing seasonal patterns","Plant crops only after floods occur"],"answer":0,"explanation":""}'::jsonb,'b0749b3e3a375c1083fcc0e0dd851154','official',NULL,NULL,'Early Humans and River Valley Civilizations'),
('original:social-studies--world-history--early-humans-and-river-valley-civilizations:social-studies--world-history--early-humans-and-river-valley-civilizations--13',1,'{"question":"What is a civilization''s social hierarchy?","choices":["A map showing only rivers","An arrangement of groups with different status, roles, or access to power","A tool for measuring crop yields","A system that gives everyone identical authority"],"answer":1,"explanation":""}'::jsonb,'de659fae30ccea40d9fcea8cda4867bc','official',NULL,NULL,'Early Humans and River Valley Civilizations'),
('original:social-studies--world-history--early-humans-and-river-valley-civilizations:social-studies--world-history--early-humans-and-river-valley-civilizations--14',1,'{"question":"Which material was commonly used in Mesopotamia to make durable writing tablets?","choices":["Silk","Bamboo","Clay","Papyrus only"],"answer":2,"explanation":""}'::jsonb,'16e4bdde05604d4ea90d467eda6307c2','official',NULL,NULL,'Early Humans and River Valley Civilizations'),
('original:social-studies--world-history--early-humans-and-river-valley-civilizations:social-studies--world-history--early-humans-and-river-valley-civilizations--15',1,'{"question":"Why might control of a river valley become a source of political power?","choices":["It guarantees that no neighboring group can trade","It makes population growth impossible","It removes the need for organized labor","It can provide access to water, farmland, and transportation routes"],"answer":3,"explanation":""}'::jsonb,'c3f1c354607d46d3064ea80a63b72976','official',NULL,NULL,'Early Humans and River Valley Civilizations'),
('original:social-studies--world-history--early-humans-and-river-valley-civilizations:social-studies--world-history--early-humans-and-river-valley-civilizations--16',1,'{"question":"Which statement best describes the role of trade in early civilizations?","choices":["Trade moved resources and ideas between communities","Trade occurred only after industrialization","Trade prevented cultural contact","Trade eliminated local production"],"answer":0,"explanation":""}'::jsonb,'598216c24b286a555c9edf22dd03b309','official',NULL,NULL,'Early Humans and River Valley Civilizations'),
('original:social-studies--world-history--early-humans-and-river-valley-civilizations:social-studies--world-history--early-humans-and-river-valley-civilizations--17',1,'{"question":"A historian finds evidence that an early town used standardized weights. What might this indicate?","choices":["The town had no market activity","People measured goods in ways that could support exchange and administration","Residents used a modern metric system","Weights were used only for building temples"],"answer":1,"explanation":""}'::jsonb,'a066e16d2e21e36e7dc1f6059d5aa6d3','official',NULL,NULL,'Early Humans and River Valley Civilizations'),
('original:social-studies--world-history--early-humans-and-river-valley-civilizations:social-studies--world-history--early-humans-and-river-valley-civilizations--18',1,'{"question":"Which early Chinese dynasty is associated with oracle bones and bronze work?","choices":["Maya","Akkadian","Shang","Ptolemaic"],"answer":2,"explanation":""}'::jsonb,'95dd922fb360ee8d49360c15920746e1','official',NULL,NULL,'Early Humans and River Valley Civilizations'),
('original:social-studies--world-history--early-humans-and-river-valley-civilizations:social-studies--world-history--early-humans-and-river-valley-civilizations--19',1,'{"question":"Why did some early governments organize labor for canals, walls, or temples?","choices":["Every project could be completed by one household","Public works eliminated social differences","Canals did not require planning or maintenance","Large projects required coordination of workers and resources"],"answer":3,"explanation":""}'::jsonb,'83aa7ca5ec22da3af9a54486030258da','official',NULL,NULL,'Early Humans and River Valley Civilizations'),
('original:social-studies--world-history--early-humans-and-river-valley-civilizations:social-studies--world-history--early-humans-and-river-valley-civilizations--20',1,'{"question":"What is a limitation of using only written records to study early civilizations?","choices":["Records may reflect the views of literate elites and omit many people''s experiences","Written records always describe every group equally","Written sources cannot be dated","Writing never provides historical evidence"],"answer":0,"explanation":""}'::jsonb,'1953c8714ec9087ddaed09bab9703916','official',NULL,NULL,'Early Humans and River Valley Civilizations'),
('original:social-studies--world-history--mesoamerican-and-andean-civilizations:social-studies--world-history--mesoamerican-and-andean-civilizations--1',1,'{"question":"Which crop became a foundation of many Mesoamerican societies?","choices":["Wheat","Maize","Barley","Potatoes only"],"answer":1,"explanation":""}'::jsonb,'1845d8170076854f1a8faaa9dfb54231','official',NULL,NULL,'Mesoamerican and Andean Civilizations'),
('original:social-studies--world-history--mesoamerican-and-andean-civilizations:social-studies--world-history--mesoamerican-and-andean-civilizations--2',1,'{"question":"Which civilization built its capital, Tenochtitlan, on an island in Lake Texcoco?","choices":["The Inca","The Olmec","The Mexica, often called the Aztec","The Moche"],"answer":2,"explanation":""}'::jsonb,'44432f7563cc9a2a2f77cf81061bf3d6','official',NULL,NULL,'Mesoamerican and Andean Civilizations'),
('original:social-studies--world-history--mesoamerican-and-andean-civilizations:social-studies--world-history--mesoamerican-and-andean-civilizations--3',1,'{"question":"What were chinampas?","choices":["Inca record-keeping cords","Maya stone calendars","Andean mountain roads","Raised agricultural plots built in shallow lake areas"],"answer":3,"explanation":""}'::jsonb,'9ec15e720647cc178d692af665b03170','official',NULL,NULL,'Mesoamerican and Andean Civilizations'),
('original:social-studies--world-history--mesoamerican-and-andean-civilizations:social-studies--world-history--mesoamerican-and-andean-civilizations--4',1,'{"question":"Which civilization created a large empire centered in the Andes with its capital at Cusco?","choices":["The Inca","The Maya","The Olmec","The Mexica"],"answer":0,"explanation":""}'::jsonb,'5335ad951d7105dc4cc35aae689f48bc','official',NULL,NULL,'Mesoamerican and Andean Civilizations'),
('original:social-studies--world-history--mesoamerican-and-andean-civilizations:social-studies--world-history--mesoamerican-and-andean-civilizations--5',1,'{"question":"Why did the Inca build extensive roads across the Andes?","choices":["To prevent all trade between settlements","To connect regions and support communication, administration, and movement","To replace agriculture with mining","To mark the edge of the Sahara"],"answer":1,"explanation":""}'::jsonb,'7ca90f95090a91391daf5a6446c0e46f','official',NULL,NULL,'Mesoamerican and Andean Civilizations'),
('original:social-studies--world-history--mesoamerican-and-andean-civilizations:social-studies--world-history--mesoamerican-and-andean-civilizations--6',1,'{"question":"What were quipu used for in the Inca Empire?","choices":["Growing maize in lake gardens","Building stone arches","Recording information with knotted cords","Tracking European ships"],"answer":2,"explanation":""}'::jsonb,'b0fe41f212d10aec93e7de17b72f77cf','official',NULL,NULL,'Mesoamerican and Andean Civilizations'),
('original:social-studies--world-history--mesoamerican-and-andean-civilizations:social-studies--world-history--mesoamerican-and-andean-civilizations--7',1,'{"question":"Which civilization is known for early monumental sculpture and influence in the Gulf Coast region of Mesoamerica?","choices":["The Inca","The Songhai","The Hittite","The Olmec"],"answer":3,"explanation":""}'::jsonb,'95b77747848a93a9379d2d53fbdca046','official',NULL,NULL,'Mesoamerican and Andean Civilizations'),
('original:social-studies--world-history--mesoamerican-and-andean-civilizations:social-studies--world-history--mesoamerican-and-andean-civilizations--8',1,'{"question":"Why did Maya city-states develop systems of writing and calendars?","choices":["They supported record keeping, ritual, political life, and tracking time","They replaced all local languages","They were used only to navigate the Atlantic","They ended the need for trade"],"answer":0,"explanation":""}'::jsonb,'7c95b25681f0d5059557f541000facd1','official',NULL,NULL,'Mesoamerican and Andean Civilizations'),
('original:social-studies--world-history--mesoamerican-and-andean-civilizations:social-studies--world-history--mesoamerican-and-andean-civilizations--9',1,'{"question":"A farming community in the Andes builds terraces on a steep slope. What is the main agricultural purpose?","choices":["To make the mountain taller","To create level planting areas and manage soil and water on hillsides","To prevent all rainfall from reaching crops","To connect the Andes to the Nile"],"answer":1,"explanation":""}'::jsonb,'05d45e6c1cf28b5c3278a2ce7336a781','official',NULL,NULL,'Mesoamerican and Andean Civilizations'),
('original:social-studies--world-history--mesoamerican-and-andean-civilizations:social-studies--world-history--mesoamerican-and-andean-civilizations--10',1,'{"question":"How did the geography of the Andes influence Inca society?","choices":["The mountains made agriculture impossible everywhere","The Andes prevented any centralized government","Mountain terrain shaped farming, transportation, and regional connections","The empire existed only on flat coastal plains"],"answer":2,"explanation":""}'::jsonb,'6d79e3103bfced8063e06eeea245d466','official',NULL,NULL,'Mesoamerican and Andean Civilizations'),
('original:social-studies--world-history--mesoamerican-and-andean-civilizations:social-studies--world-history--mesoamerican-and-andean-civilizations--11',1,'{"question":"What does the term Mesoamerica refer to?","choices":["The entire South American continent","A medieval European kingdom","A river valley in eastern Africa","A cultural region of present-day Mexico and Central America"],"answer":3,"explanation":""}'::jsonb,'1eb1b45f2b7fa709042b4265afff9ad8','official',NULL,NULL,'Mesoamerican and Andean Civilizations'),
('original:social-studies--world-history--mesoamerican-and-andean-civilizations:social-studies--world-history--mesoamerican-and-andean-civilizations--12',1,'{"question":"Why was trade important among Mesoamerican societies?","choices":["It moved goods such as obsidian, cacao, textiles, and ideas across regions","It made local resources unnecessary","It prevented political alliances","It occurred only after Spanish conquest"],"answer":0,"explanation":""}'::jsonb,'7dfdddb13b21154f5f3535832bac5a99','official',NULL,NULL,'Mesoamerican and Andean Civilizations'),
('original:social-studies--world-history--mesoamerican-and-andean-civilizations:social-studies--world-history--mesoamerican-and-andean-civilizations--13',1,'{"question":"A historian compares Spanish accounts with Indigenous sources about the conquest of the Mexica Empire. Why use both?","choices":["Spanish accounts always contain every viewpoint","Different sources can reveal perspective, bias, and experiences omitted by one account","Indigenous sources cannot provide historical evidence","Comparing accounts eliminates the need for context"],"answer":1,"explanation":""}'::jsonb,'402466032345994df278eda4d9133215','official',NULL,NULL,'Mesoamerican and Andean Civilizations'),
('original:social-studies--world-history--mesoamerican-and-andean-civilizations:social-studies--world-history--mesoamerican-and-andean-civilizations--14',1,'{"question":"Which statement about the Maya is accurate?","choices":["The Maya formed a single empire that controlled all of South America","Maya civilization began after the Spanish conquest","Maya peoples built city-states and developed writing, mathematics, and astronomy","The Maya had no agricultural systems"],"answer":2,"explanation":""}'::jsonb,'fc7646b60217b58bd732e9aa4135d4f7','official',NULL,NULL,'Mesoamerican and Andean Civilizations'),
('original:social-studies--world-history--mesoamerican-and-andean-civilizations:social-studies--world-history--mesoamerican-and-andean-civilizations--15',1,'{"question":"What challenge did the Inca face in governing a large empire across varied terrain?","choices":["Maintaining contact across a single small island","Managing a navy on the Mediterranean Sea","Growing rice in the Nile Delta","Communicating and transporting people and goods across long distances and mountains"],"answer":3,"explanation":""}'::jsonb,'dd9d129b3479713232bfca9887c15136','official',NULL,NULL,'Mesoamerican and Andean Civilizations'),
('original:social-studies--world-history--mesoamerican-and-andean-civilizations:social-studies--world-history--mesoamerican-and-andean-civilizations--16',1,'{"question":"Why were potatoes and other high-altitude crops important in the Andes?","choices":["They were adapted to local environments and supported food supplies","They could grow only in tropical rainforests","They replaced all trade","They were first introduced from Europe before the Inca"],"answer":0,"explanation":""}'::jsonb,'b72c8923a17959cf340ccf068bec79f0','official',NULL,NULL,'Mesoamerican and Andean Civilizations')
insert into public.question_content_versions(source_key,version_number,question,content_hash,source_type,creator_id,source_set_id,source_title) values
('original:social-studies--world-history--mesoamerican-and-andean-civilizations:social-studies--world-history--mesoamerican-and-andean-civilizations--17',1,'{"question":"Which feature helped the Mexica expand their power in the Valley of Mexico?","choices":["A network of transatlantic steamships","Military alliances and control of tribute from subject communities","The construction of the Great Wall","Control of the Sahara''s caravan routes"],"answer":1,"explanation":""}'::jsonb,'43166a15c43796394bb34e1d3359e536','official',NULL,NULL,'Mesoamerican and Andean Civilizations'),
('original:social-studies--world-history--mesoamerican-and-andean-civilizations:social-studies--world-history--mesoamerican-and-andean-civilizations--18',1,'{"question":"A city grows on a lake island and uses raised fields to increase food production. Which example best fits this description?","choices":["Cusco and quipu","Machu Picchu and Roman aqueducts","Tenochtitlan and chinampas","Chichen Itza and Nile irrigation"],"answer":2,"explanation":""}'::jsonb,'f4bdb766be281d52e764420a3db205bf','official',NULL,NULL,'Mesoamerican and Andean Civilizations'),
('original:social-studies--world-history--mesoamerican-and-andean-civilizations:social-studies--world-history--mesoamerican-and-andean-civilizations--19',1,'{"question":"Why should the terms ''Aztec'' and ''Mexica'' be used carefully in historical writing?","choices":["They describe the Inca Empire","They are names for the Maya writing system","They were created by the Olmec","They can refer to related but not identical political or cultural groupings"],"answer":3,"explanation":""}'::jsonb,'9578f795a8568f23763ae8ce9314d7b7','official',NULL,NULL,'Mesoamerican and Andean Civilizations'),
('original:social-studies--world-history--mesoamerican-and-andean-civilizations:social-studies--world-history--mesoamerican-and-andean-civilizations--20',1,'{"question":"What is one lasting effect of Spanish conquest on Indigenous communities in the Americas?","choices":["Population loss, political change, and cultural transformation, alongside continued Indigenous survival and adaptation","The disappearance of all Indigenous languages and traditions","No changes to land ownership or government","The end of all cultural exchange"],"answer":0,"explanation":""}'::jsonb,'dc256734a9d18cb2a29f012e43a45822','official',NULL,NULL,'Mesoamerican and Andean Civilizations'),
('original:social-studies--world-history--byzantine-empire-and-islamic-world:social-studies--world-history--byzantine-empire-and-islamic-world--1',1,'{"question":"What was the capital of the Byzantine Empire for most of its history?","choices":["Rome","Constantinople","Baghdad","Alexandria"],"answer":1,"explanation":""}'::jsonb,'ac70bc4f27b970d21682ffef2611b3d0','official',NULL,NULL,'Byzantine Empire and Islamic World'),
('original:social-studies--world-history--byzantine-empire-and-islamic-world:social-studies--world-history--byzantine-empire-and-islamic-world--2',1,'{"question":"The Byzantine Empire developed from the eastern portion of","choices":["the Persian Empire","the Mongol Empire","the Roman Empire","the Carolingian Empire"],"answer":2,"explanation":""}'::jsonb,'a64d78ba875fc4182aa35c3f72a7949e','official',NULL,NULL,'Byzantine Empire and Islamic World'),
('original:social-studies--world-history--byzantine-empire-and-islamic-world:social-studies--world-history--byzantine-empire-and-islamic-world--3',1,'{"question":"What was the Justinian Code?","choices":["A trade agreement between Byzantium and China","A list of Islamic pilgrimage sites","A system of Inca record keeping","A compilation and organization of Roman laws under Emperor Justinian"],"answer":3,"explanation":""}'::jsonb,'5df9a690734dda2efb5f12565d0a4970','official',NULL,NULL,'Byzantine Empire and Islamic World'),
('original:social-studies--world-history--byzantine-empire-and-islamic-world:social-studies--world-history--byzantine-empire-and-islamic-world--4',1,'{"question":"Why was Constantinople a strategically important city?","choices":["It connected trade routes between Europe and Asia and controlled access between seas","It was located in the Sahara far from trade","It had no natural harbor or defenses","It was the capital of the Song dynasty"],"answer":0,"explanation":""}'::jsonb,'b3fc75e7e1c48511f6d8d9192cf43e41','official',NULL,NULL,'Byzantine Empire and Islamic World'),
('original:social-studies--world-history--byzantine-empire-and-islamic-world:social-studies--world-history--byzantine-empire-and-islamic-world--5',1,'{"question":"Which architectural landmark was first built as a Byzantine cathedral under Justinian?","choices":["The Parthenon","Hagia Sophia","The Dome of the Rock","The Colosseum"],"answer":1,"explanation":""}'::jsonb,'818fa7191928c5afea50e11d202dc9b1','official',NULL,NULL,'Byzantine Empire and Islamic World'),
('original:social-studies--world-history--byzantine-empire-and-islamic-world:social-studies--world-history--byzantine-empire-and-islamic-world--6',1,'{"question":"What event is commonly associated with the formal split between the Roman Catholic and Eastern Orthodox churches?","choices":["The Council of Nicaea","The fall of the Western Roman Empire","The Great Schism of 1054","The beginning of the Crusades"],"answer":2,"explanation":""}'::jsonb,'0cf486d43c5f56e9d6d5d9add1962de0','official',NULL,NULL,'Byzantine Empire and Islamic World'),
('original:social-studies--world-history--byzantine-empire-and-islamic-world:social-studies--world-history--byzantine-empire-and-islamic-world--7',1,'{"question":"Where did Islam originate in the seventh century?","choices":["The Iberian Peninsula","The Indus Valley","The Scandinavian Peninsula","The Arabian Peninsula"],"answer":3,"explanation":""}'::jsonb,'055360c3219e90b9f9120c5a01e74d67','official',NULL,NULL,'Byzantine Empire and Islamic World'),
('original:social-studies--world-history--byzantine-empire-and-islamic-world:social-studies--world-history--byzantine-empire-and-islamic-world--8',1,'{"question":"What is the Qur''an in Islam?","choices":["The central sacred text of Islam","A Byzantine law code","A Persian royal title","A trade route across the Sahara"],"answer":0,"explanation":""}'::jsonb,'5e4a6435cf5526d9f72109d4b4711149','official',NULL,NULL,'Byzantine Empire and Islamic World'),
('original:social-studies--world-history--byzantine-empire-and-islamic-world:social-studies--world-history--byzantine-empire-and-islamic-world--9',1,'{"question":"Why did cities such as Baghdad become important centers of learning in parts of the medieval Islamic world?","choices":["They prohibited the study of mathematics","They supported scholarship, translation, trade, and exchange of ideas","They were isolated from trade routes","They replaced every other capital in the region"],"answer":1,"explanation":""}'::jsonb,'280be327542edd18bcc501296e4f6dd1','official',NULL,NULL,'Byzantine Empire and Islamic World'),
('original:social-studies--world-history--byzantine-empire-and-islamic-world:social-studies--world-history--byzantine-empire-and-islamic-world--10',1,'{"question":"Which institution is associated with scholarly activity in Abbasid Baghdad?","choices":["The University of Bologna","The Library of Alexandria under Ptolemy","The House of Wisdom","The Royal Society"],"answer":2,"explanation":""}'::jsonb,'31a2db97cc086e161a07175645a18688','official',NULL,NULL,'Byzantine Empire and Islamic World'),
('original:social-studies--world-history--byzantine-empire-and-islamic-world:social-studies--world-history--byzantine-empire-and-islamic-world--11',1,'{"question":"Merchants traveling across Afro-Eurasian trade networks helped spread","choices":["only one language and religion","a single political government","the same climate in every region","goods, technologies, and ideas among regions"],"answer":3,"explanation":""}'::jsonb,'6e3b4f4e2bb2da38e0d4a7301bbb7ec3','official',NULL,NULL,'Byzantine Empire and Islamic World'),
('original:social-studies--world-history--byzantine-empire-and-islamic-world:social-studies--world-history--byzantine-empire-and-islamic-world--12',1,'{"question":"How did the Byzantine Empire preserve aspects of classical learning?","choices":["Through the use and transmission of Greek and Roman texts and traditions","By banning all written works","By replacing every text with oral law","By isolating itself from neighboring societies"],"answer":0,"explanation":""}'::jsonb,'5cf8aedd79561b4ada5b1bffab696593','official',NULL,NULL,'Byzantine Empire and Islamic World'),
('original:social-studies--world-history--byzantine-empire-and-islamic-world:social-studies--world-history--byzantine-empire-and-islamic-world--13',1,'{"question":"A historian studying medieval trade finds coins from several regions in one port city. What is a reasonable conclusion?","choices":["The coins prove one empire controlled every region","The city participated in long-distance exchange networks","The city had no local economy","The coins establish the exact number of merchants"],"answer":1,"explanation":""}'::jsonb,'b668da6aaaa72b0eeaf8c69bed505378','official',NULL,NULL,'Byzantine Empire and Islamic World'),
('original:social-studies--world-history--byzantine-empire-and-islamic-world:social-studies--world-history--byzantine-empire-and-islamic-world--14',1,'{"question":"What was one effect of the expansion of Islamic caliphates in the centuries after Islam began?","choices":["Every region adopted identical customs immediately","Trade ended between the Mediterranean and Asia","New political territories became connected through administration and trade, with varied local societies","The Byzantine Empire disappeared in the seventh century"],"answer":2,"explanation":""}'::jsonb,'dbd8c8fd04b9e13a34c02da938ee4c69','official',NULL,NULL,'Byzantine Empire and Islamic World'),
('original:social-studies--world-history--byzantine-empire-and-islamic-world:social-studies--world-history--byzantine-empire-and-islamic-world--15',1,'{"question":"Why is it more accurate to speak of diverse societies within the medieval Islamic world than one uniform culture?","choices":["Islamic societies existed only in one city","Trade prevented cultural interaction","Every caliph ruled all Muslim communities in the same way","Peoples across a wide region had varied languages, traditions, and political histories"],"answer":3,"explanation":""}'::jsonb,'d009f21c919559c826e878ff391a43f7','official',NULL,NULL,'Byzantine Empire and Islamic World'),
('original:social-studies--world-history--byzantine-empire-and-islamic-world:social-studies--world-history--byzantine-empire-and-islamic-world--16',1,'{"question":"Which challenge contributed to the Byzantine Empire''s decline before Constantinople fell in 1453?","choices":["Military pressures, territorial losses, and economic strain over time","The empire had no capital city","The empire never faced external rivals","The empire lost control of the Atlantic Ocean"],"answer":0,"explanation":""}'::jsonb,'356cb1fa52d920e3281c0d576f5b7134','official',NULL,NULL,'Byzantine Empire and Islamic World'),
('original:social-studies--world-history--byzantine-empire-and-islamic-world:social-studies--world-history--byzantine-empire-and-islamic-world--17',1,'{"question":"Which city was captured by Ottoman forces in 1453, ending the Byzantine Empire?","choices":["Carthage","Constantinople","Cordoba","Damascus"],"answer":1,"explanation":""}'::jsonb,'73204ca94f1484b6732705a68b5ca3fa','official',NULL,NULL,'Byzantine Empire and Islamic World'),
