('original:social-studies--world-history--imperialism-and-global-change:social-studies--world-history--imperialism-and-global-change--1',1,'{"question":"Imperialism is best defined as","choices":["the exchange of goods between equal trading partners only","a policy or practice of extending a state''s influence or control over other peoples or territories","the movement from rural areas to cities","a system of local self-government"],"answer":1,"explanation":""}'::jsonb,'6f77459553a9e3214fa2002b8d46eb04','official',NULL,NULL,'Imperialism and Global Change'),
('original:social-studies--world-history--imperialism-and-global-change:social-studies--world-history--imperialism-and-global-change--2',1,'{"question":"Which factor helped European imperialism expand during the nineteenth century?","choices":["European states had no access to ships","Industrial production reduced demand for resources","Industrial economies sought raw materials, markets, and strategic advantages","Imperial powers rejected overseas investment"],"answer":2,"explanation":""}'::jsonb,'450724af17004cbcc9ee5aeeac1934e7','official',NULL,NULL,'Imperialism and Global Change'),
