('original:social-studies--world-history--imperialism-and-global-change:social-studies--world-history--imperialism-and-global-change--9',1,'{"question":"Why did imperial powers value strategic ports and canals?","choices":["They prevented ships from carrying goods","They could support military movement and protect trade routes","They eliminated the need for navies","They had no connection to overseas empire"],"answer":1,"explanation":""}'::jsonb,'72ec759f21221b285d34979a247ba248','official',NULL,NULL,'Imperialism and Global Change'),
('original:social-studies--world-history--imperialism-and-global-change:social-studies--world-history--imperialism-and-global-change--10',1,'{"question":"The Meiji government in Japan pursued rapid modernization partly in response to","choices":["the collapse of the Inca Empire","the end of the Silk Road in antiquity","the threat of Western imperial pressure","the discovery of the Nile"],"answer":2,"explanation":""}'::jsonb,'d82b65bc4e7b54f2f6d7cca89ff6e3df','official',NULL,NULL,'Imperialism and Global Change'),
('original:social-studies--world-history--imperialism-and-global-change:social-studies--world-history--imperialism-and-global-change--11',1,'{"question":"What was one effect of imperial borders drawn without regard to local communities?","choices":["They always matched existing cultural boundaries","They removed all political conflict","They prevented later debates about sovereignty","They could divide related groups or combine communities with differing interests"],"answer":3,"explanation":""}'::jsonb,'357749b279e38f4434270d87156fa30f','official',NULL,NULL,'Imperialism and Global Change'),
('original:social-studies--world-history--imperialism-and-global-change:social-studies--world-history--imperialism-and-global-change--12',1,'{"question":"Why is it inaccurate to describe colonized peoples as passive during imperial expansion?","choices":["People resisted, negotiated, adapted, and built political movements in varied ways","Imperial powers acted without any local response","Colonized societies had no leaders or institutions","Resistance never affected imperial policy"],"answer":0,"explanation":""}'::jsonb,'1838df7a0cef40d188fefa83ab2c7a76','official',NULL,NULL,'Imperialism and Global Change'),
('original:social-studies--world-history--imperialism-and-global-change:social-studies--world-history--imperialism-and-global-change--13',1,'{"question":"Which event is associated with the beginning of the Scramble for Africa?","choices":["The formation of the Mali Empire","The rapid partition of African territories among European powers in the late nineteenth century","The opening of the Suez Canal in ancient Egypt","The end of the transatlantic slave trade in the fifteenth century"],"answer":1,"explanation":""}'::jsonb,'f6059607392ad8aa3f554ae895dff9e5','official',NULL,NULL,'Imperialism and Global Change'),
('original:social-studies--world-history--imperialism-and-global-change:social-studies--world-history--imperialism-and-global-change--14',1,'{"question":"A colonial government builds railways mainly to move minerals from interior regions to ports. What does this suggest about infrastructure under imperialism?","choices":["It always connected every community equally","It was unrelated to economic goals","It often served extraction and export as well as local transportation","It eliminated colonial control"],"answer":2,"explanation":""}'::jsonb,'7f0f7bf83b02d39ceb360ede257c0d9e','official',NULL,NULL,'Imperialism and Global Change'),
('original:social-studies--world-history--imperialism-and-global-change:social-studies--world-history--imperialism-and-global-change--15',1,'{"question":"Which statement best describes economic imperialism?","choices":["A country''s citizens vote in local elections","A trade exchange with equal bargaining power","A policy of avoiding all foreign investment","A powerful state or company gains influence over another economy without necessarily annexing its territory"],"answer":3,"explanation":""}'::jsonb,'9c6b8d81e90a7f53a2181cd0a785be89','official',NULL,NULL,'Imperialism and Global Change'),
('original:social-studies--world-history--imperialism-and-global-change:social-studies--world-history--imperialism-and-global-change--16',1,'{"question":"Why did nationalist movements grow in many colonized regions?","choices":["People sought greater political control and challenged foreign rule","Imperial rule always granted immediate independence","Nationalism opposed every local culture","Colonial borders prevented political organization"],"answer":0,"explanation":""}'::jsonb,'dd200ebe112f0da35520eecdab7bc44e','official',NULL,NULL,'Imperialism and Global Change'),
('original:social-studies--world-history--imperialism-and-global-change:social-studies--world-history--imperialism-and-global-change--17',1,'{"question":"What was one consequence of imperial competition among European powers?","choices":["It ended all conflicts in Europe","It increased international rivalries and contributed to tensions before World War I","It created a single European government","It removed competition for resources"],"answer":1,"explanation":""}'::jsonb,'67708ba4210652707baae3fc67682814','official',NULL,NULL,'Imperialism and Global Change'),
('original:social-studies--world-history--imperialism-and-global-change:social-studies--world-history--imperialism-and-global-change--18',1,'{"question":"A historian compares colonial tax records with oral histories from residents. What can this reveal?","choices":["The exact opinions of every resident","That taxation affected no local economy","How official policies affected people whose experiences may be absent from government records","That oral histories cannot be evidence"],"answer":2,"explanation":""}'::jsonb,'e1f6f08bcd739ca1b6a34923d61bfb4c','official',NULL,NULL,'Imperialism and Global Change'),
('original:social-studies--world-history--imperialism-and-global-change:social-studies--world-history--imperialism-and-global-change--19',1,'{"question":"Which term describes a territory controlled politically or economically by an outside power?","choices":["City-state","Federation","Common market","Colony"],"answer":3,"explanation":""}'::jsonb,'0e41f4a69f21621fd0bcebfacd3d940c','official',NULL,NULL,'Imperialism and Global Change'),
('original:social-studies--world-history--imperialism-and-global-change:social-studies--world-history--imperialism-and-global-change--20',1,'{"question":"Why can imperialism''s long-term effects differ across regions?","choices":["Local histories, forms of resistance, colonial policies, and postcolonial choices varied","Every empire used identical policies everywhere","Geography has no effect on historical outcomes","Independence produced identical economies in all countries"],"answer":0,"explanation":""}'::jsonb,'c8338630dadfbf6f7fe60ac8198056f0','official',NULL,NULL,'Imperialism and Global Change'),
('original:social-studies--world-history--globalization-and-contemporary-world:social-studies--world-history--globalization-and-contemporary-world--1',1,'{"question":"Globalization refers to","choices":["the end of all international communication","growing connections among people, economies, and societies across national borders","the isolation of local economies","a political system used by every country"],"answer":1,"explanation":""}'::jsonb,'464c107c2c297516eebb32f7d0c5b5ff','official',NULL,NULL,'Globalization and the Contemporary World'),
('original:social-studies--world-history--globalization-and-contemporary-world:social-studies--world-history--globalization-and-contemporary-world--2',1,'{"question":"A supply chain is","choices":["a list of a company''s employees","a treaty that sets national borders","the network of steps and organizations involved in producing and delivering a good","a system for measuring population density"],"answer":2,"explanation":""}'::jsonb,'36f736d8628ec612e4502b4a5e16dcce','official',NULL,NULL,'Globalization and the Contemporary World'),
('original:social-studies--world-history--globalization-and-contemporary-world:social-studies--world-history--globalization-and-contemporary-world--3',1,'{"question":"How can digital communication contribute to globalization?","choices":["It prevents people from contacting other countries","It makes transportation unnecessary for every product","It eliminates differences in language","It allows information and services to move quickly across long distances"],"answer":3,"explanation":""}'::jsonb,'39ebf71d1ea9332438a431d825990a1c','official',NULL,NULL,'Globalization and the Contemporary World'),
('original:social-studies--world-history--globalization-and-contemporary-world:social-studies--world-history--globalization-and-contemporary-world--4',1,'{"question":"A company designs a product in one country, sources parts in several others, and assembles it elsewhere. This is an example of","choices":["a global supply chain","subsistence production","economic isolation","local barter only"],"answer":0,"explanation":""}'::jsonb,'2307a43c15d7081640505d063f346de2','official',NULL,NULL,'Globalization and the Contemporary World'),
('original:social-studies--world-history--globalization-and-contemporary-world:social-studies--world-history--globalization-and-contemporary-world--5',1,'{"question":"What is outsourcing?","choices":["Moving all production back to the home country","Contracting work or services to an outside provider, sometimes in another country","Eliminating all paid work","Exchanging goods without prices"],"answer":1,"explanation":""}'::jsonb,'37d06038f8b975172b2d4a4eef6a8c05','official',NULL,NULL,'Globalization and the Contemporary World'),
('original:social-studies--world-history--globalization-and-contemporary-world:social-studies--world-history--globalization-and-contemporary-world--6',1,'{"question":"Why might companies relocate production to another country?","choices":["To avoid all shipping and communication","Because international laws require every firm to relocate","To access workers, suppliers, markets, or lower costs","To eliminate competition from local businesses"],"answer":2,"explanation":""}'::jsonb,'9f39e8ce06630b232701c4f4972f2ae0','official',NULL,NULL,'Globalization and the Contemporary World'),
('original:social-studies--world-history--globalization-and-contemporary-world:social-studies--world-history--globalization-and-contemporary-world--7',1,'{"question":"Which group helps set and monitor rules for international trade among its members?","choices":["International Court of Justice only","World Health Organization","North Atlantic Treaty Organization","World Trade Organization"],"answer":3,"explanation":""}'::jsonb,'edebdd0deaa4caaa7c29cc4e13e8e16b','official',NULL,NULL,'Globalization and the Contemporary World'),
('original:social-studies--world-history--globalization-and-contemporary-world:social-studies--world-history--globalization-and-contemporary-world--8',1,'{"question":"A product''s price rises after a key port closes. What does this show about global supply chains?","choices":["A disruption in one location can affect production and prices elsewhere","Supply chains are always local","Ports have no effect on trade","Prices cannot respond to transportation changes"],"answer":0,"explanation":""}'::jsonb,'829af39d8ac48d4d85245ebed43dee20','official',NULL,NULL,'Globalization and the Contemporary World'),
('original:social-studies--world-history--globalization-and-contemporary-world:social-studies--world-history--globalization-and-contemporary-world--9',1,'{"question":"What is cultural diffusion?","choices":["The measurement of national income","The spread of cultural ideas or practices between groups","The movement of tectonic plates","A type of agricultural irrigation"],"answer":1,"explanation":""}'::jsonb,'bb451661970126bdab275dc8b7fcf5b3','official',NULL,NULL,'Globalization and the Contemporary World'),
('original:social-studies--world-history--globalization-and-contemporary-world:social-studies--world-history--globalization-and-contemporary-world--10',1,'{"question":"Why can globalization create both opportunities and challenges for workers?","choices":["It guarantees higher wages for every worker","It prevents industries from changing","It can expand markets and jobs while also increasing competition and restructuring employment","It eliminates differences in working conditions"],"answer":2,"explanation":""}'::jsonb,'97a7c3e4d64d9765f36f2a31a9830a34','official',NULL,NULL,'Globalization and the Contemporary World'),
('original:social-studies--world-history--globalization-and-contemporary-world:social-studies--world-history--globalization-and-contemporary-world--11',1,'{"question":"What is one possible environmental effect of increased global trade?","choices":["Trade always reduces resource consumption","Trade has no connection to transportation","Global shipping eliminates pollution","More transportation and production can increase emissions and resource use"],"answer":3,"explanation":""}'::jsonb,'32d6f6d0dab2e38e768027e90ca7e816','official',NULL,NULL,'Globalization and the Contemporary World'),
('original:social-studies--world-history--globalization-and-contemporary-world:social-studies--world-history--globalization-and-contemporary-world--12',1,'{"question":"A country exports a large share of its products to one trading partner. What risk may it face?","choices":["A downturn or policy change in that partner''s market may reduce export demand","Its exports become independent of foreign demand","The partner cannot affect trade","Its currency can never fluctuate"],"answer":0,"explanation":""}'::jsonb,'8bf4350e96fe5af690af9ca67f6e71ea','official',NULL,NULL,'Globalization and the Contemporary World'),
('original:social-studies--world-history--globalization-and-contemporary-world:social-studies--world-history--globalization-and-contemporary-world--13',1,'{"question":"What does the digital divide describe?","choices":["The difference between two computer file formats","Unequal access to digital technologies and reliable internet","A gap between a country''s borders and its coast","The spread of a language through migration"],"answer":1,"explanation":""}'::jsonb,'8c945da55193a8b878b7e3bd11a03661','official',NULL,NULL,'Globalization and the Contemporary World'),
('original:social-studies--world-history--globalization-and-contemporary-world:social-studies--world-history--globalization-and-contemporary-world--14',1,'{"question":"Why is comparative advantage used to explain some patterns of international trade?","choices":["Every country produces every good at identical cost","Trade requires countries to have the same resources","Countries can benefit by specializing in goods with lower opportunity costs and trading","Comparative advantage guarantees equal incomes"],"answer":2,"explanation":""}'::jsonb,'6b5682ccfe2c80abdd9b8ca091244a93','official',NULL,NULL,'Globalization and the Contemporary World'),
('original:social-studies--world-history--globalization-and-contemporary-world:social-studies--world-history--globalization-and-contemporary-world--15',1,'{"question":"A global clothing brand changes its advertising to fit local languages and customs. This is an example of","choices":["ending cultural exchange","replacing all local businesses","eliminating a supply chain","adapting a global product or message to local contexts"],"answer":3,"explanation":""}'::jsonb,'0d8c2bc83f481de80b37fab2511e7c20','official',NULL,NULL,'Globalization and the Contemporary World'),
('original:social-studies--world-history--globalization-and-contemporary-world:social-studies--world-history--globalization-and-contemporary-world--16',1,'{"question":"How can migration contribute to globalization?","choices":["People carry skills, languages, ideas, and family connections across borders","Migration prevents cultural and economic ties","Migrants cannot affect labor markets","Migration occurs only during wars"],"answer":0,"explanation":""}'::jsonb,'6895e9b26d5d5576a65c2ec127d49c39','official',NULL,NULL,'Globalization and the Contemporary World')
